class Resume ______ Cloneable {
    private String name;
    private String company;

    public Resume(String name) {
        this.name = name;
    }
    public void setCompany(String company) {
        this.company = company;
    }

    public Resume clone() {
        try {
            return (Resume) super.clone();
        } catch (CloneNotSupportedException e) {
            return null;
        }
